const std=@import("std");
fn putd(out:[*]u8,p:usize,x:f64) void {const b=@as(u64,@bitCast(x));for(0..8)|k|out[p+k]=@truncate(b>>(8*k));}
fn token(v:[*]const i64,p:usize,n:usize,key:*u64) bool {key.*=0;for(0..n)|i|{var x=v[p+i];if(x>=65 and x<=90)x+=32;if(!((x>=97 and x<=122)or(x>=48 and x<=57)or x==39))return false;key.*=key.**128+@as(u64,@intCast(x));}return true;}
export fn naive_bayes_text_classification(v:[*]const i64,n:usize,out:[*]u8,cap:usize)i64 {if(n<7)return -1;const d=v[0];const alpha=v[1];if(d<2 or d>6 or alpha<1 or alpha>10000)return -1;var words=[_]u64{0}**6;var labels=[_]usize{0}**6;var seen=[_]bool{false}**2;var total=[_]usize{0}**2;var p:usize=2;for(0..@intCast(d))|i|{if(p+2>n)return -1;const lab=v[p];const len=v[p+1];p+=2;if(lab<0 or lab>1 or len<0 or len>8 or p+@as(usize,@intCast(len))>n)return -1;if(!token(v,p,@intCast(len),&words[i]))return -1;labels[i]=@intCast(lab);seen[labels[i]]=true;if(len>0)total[labels[i]]+=1;p+=@intCast(len);}if(p>=n)return -1;const ql=v[p];p+=1;if(ql<0 or ql>8 or p+@as(usize,@intCast(ql))!=n or !seen[0] or !seen[1])return -1;var q:u64=0;if(!token(v,p,@intCast(ql),&q))return -1;var vocab:usize=0;for(0..@intCast(d))|i|{if(words[i]!=0){var fresh=true;for(0..i)|j|{if(words[i]==words[j])fresh=false;}if(fresh)vocab+=1;}}if(vocab==0 and ql>0)return -1;if(cap<16)return -2;var s=[_]f64{0}**2;for(0..2)|c|{var docs:usize=0;var count:usize=0;for(0..@intCast(d))|i|{if(labels[i]==c){docs+=1;if(ql>0 and words[i]==q)count+=1;}}s[c]=@log(@as(f64,@floatFromInt(docs))/@as(f64,@floatFromInt(d)));if(ql>0){const a=@as(f64,@floatFromInt(alpha))/1000.0;s[c]+=@log((@as(f64,@floatFromInt(count))+a)/(@as(f64,@floatFromInt(total[c]))+a*@as(f64,@floatFromInt(vocab))));}}const h=@max(s[0],s[1]);const a=@exp(s[0]-h);const b=@exp(s[1]-h);putd(out,0,a/(a+b));putd(out,8,b/(a+b));return 16;}
